PRICE_TABLE_VERSION = "2026-11-14.1"

# Effective-dated step-ups (per-prompt $ audit routing, 2026-11-14; his
# word via CoS, FinOps coordinating; live BEFORE the step dates).
# (provider, model) -> [(effective_from ISO date, in, out, note), ...]
# A step applies to dispatches ON/AFTER its date. The Jan-1 Flash step
# lands when FinOps supplies the audit's exact post-intro rates.
PRICE_STEPS = {
    ("google", "gemini-4-carbon"): [
        ("2026-12-01", 4.00, 20.00,
         "intro ends 2026-11-30; $4/$20 from 2026-12-01 (I&A prep record datum on the base row)"),
    ],
    ("google", "gemini-4-argon"): [
        ("2026-12-01", 4.00, 20.00,
         "intro ends 2026-11-30; $4/$20 from 2026-12-01 (base row source note)"),
    ],
    ("google", "gemini-3.8-flash"): [
        ("2027-01-01", 1.50, 7.50,
         "intro $0.75/$3.75 through 2026-12-31; $1.50/$7.50 from 2027-01-01 (Google pricing page, read 2026-11-14; matches the audit figures)"),
    ],
    ("google", "gemini-3.6-flash"): [
        ("2027-01-01", 1.50, 7.50,
         "intro $0.75/$3.75 through 2026-12-31; $1.50/$7.50 from 2027-01-01 (Google pricing page, read 2026-11-14 — resolves the NEEDS-SOURCE on this row)"),
    ],
}


def price_info(provider: str, model: str, on_date: str | None = None):
    """Return (input, output, source) for a lane model, or raise KeyError.

    on_date (ISO YYYY-MM-DD) selects effective-dated step rates;
    default = today (UTC). A dispatch prices at ITS OWN date's rate."""
    key = (provider, model)
    if key not in PRICES:
        raise KeyError(
            f"no published price for {provider}/{model}; add a sourced entry to pricing.py before dispatching"
        )
    price_in, price_out, source = PRICES[key]
    if on_date is None:
        from datetime import datetime, timezone
        on_date = datetime.now(timezone.utc).date().isoformat()
    for eff, s_in, s_out, note in PRICE_STEPS.get(key, []):
        if on_date >= eff:
            price_in, price_out = s_in, s_out
            source = f"{source} | STEP {eff}: {note}"
    return price_in, price_out, source


def estimate_cost_usd(provider: str, model: str, tokens_in: int, tokens_out: int,
                      on_date: str | None = None) -> float:
    """Cost of a dispatch from ACTUAL usage counts at published rates."""
    price_in, price_out, _ = price_info(provider, model, on_date=on_date)
    return (tokens_in * price_in + tokens_out * price_out) / 1_000_000
